static Optional<String> findSpell(String name) {
    if (name.equals("Fireball")) return Optional.of("Fireball");
    return Optional.empty();
}

System.out.println(findSpell("Fireball").orElse("Spell not found"));
System.out.println(findSpell("Unknown").orElse("Spell not found"));

static int sum(int... numbers) {
    int total = 0;
    for (int n : numbers) total += n;
    return total;
}
System.out.println(sum(1, 2, 3, 4, 5)); // 15

